const esc = (s: string) => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
export const fillArt = (tpl: string, slots: Record<string, string> = {}) =>
  tpl.replace(/\{\{([^}]+)\}\}/g, (_m, k: string) => esc(slots[k.trim()] ?? ''));
